import * as THREE from 'three/webgpu';
import { texture, uv, color, mix, positionLocal, mx_noise_float } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'pricing-card-1-label';
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const inkColor = color('#16161d');
  const surfaceColor = color('#0b0b10');
  const accentColor = color('#ff2a38');

  const uvNode = uv();

  const grain = mx_noise_float(positionLocal.mul(80.0)).mul(0.03);

  const gradient = mix(surfaceColor, inkColor, uvNode.y.clamp(0.0, 1.0));
  const accentEdge = uvNode.x.smoothstep(0.0, 0.04).oneMinus().mul(accentColor).mul(0.4);

  const baseColorNode = gradient.add(grain).add(accentEdge);

  const material = new THREE.MeshBasicNodeMaterial({
    transparent: true,
  });
  material.colorNode = baseColorNode;

  let imageTexture = null;
  const imgUrl = config?.assets?.imageUrl || '/prism-mock/home/nodes/orb-decor.png';
  try {
    imageTexture = ctx.textureLoader.load(imgUrl);
  } catch (e) {
    imageTexture = null;
  }

  if (imageTexture) {
    imageTexture.colorSpace = THREE.SRGBColorSpace;
    const texNode = texture(imageTexture, uvNode);
    material.colorNode = mix(baseColorNode, texNode.rgb, texNode.a.mul(0.6));
  }

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'pricing-card-1-plane';
  group.add(mesh);

  // Render all text content entries via ctx.fontAtlas / createTextMesh
  const textMeshes = [];
  const textContent = Array.isArray(config?.textContent) ? config.textContent : [];

  const sizeForRole = (role) => {
    switch (role) {
      case 'hero': return 0.62;
      case 'headline': return 0.34;
      case 'subhead': return 0.2;
      case 'body': return 0.13;
      case 'caption': return 0.09;
      default: return 0.2;
    }
  };

  if (textContent.length > 0) {
    textContent.forEach((entry, i) => {
      const role = entry.role || 'headline';
      const size = sizeForRole(role);
      const weight = entry.weight || 400;
      const tm = createTextMesh(ctx.fontAtlas, {
        text: entry.text,
        font: 'Lora',
        weight,
        size,
        color: '#e8ecf2',
        align: 'center',
        anchor: 'center',
      });
      tm.position.set(0, -i * (size * 1.2), 0.01);
      group.add(tm);
      textMeshes.push(tm);
    });
  } else {
    // Fallback: ensure spec text content ("Pricing 1") is still rendered
    const tm = createTextMesh(ctx.fontAtlas, {
      text: 'Pricing 1',
      font: 'Lora',
      weight: 400,
      size: sizeForRole('headline'),
      color: '#e8ecf2',
      align: 'center',
      anchor: 'center',
    });
    tm.position.set(0, 0, 0.01);
    group.add(tm);
    textMeshes.push(tm);
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (imageTexture) imageTexture.dispose();
    textMeshes.forEach((tm) => {
      if (tm.geometry) tm.geometry.dispose();
      if (tm.material) tm.material.dispose();
    });
  };

  return group;
}
